// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: an address caller (could be owner or non-owner) and an address newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses in full domain; forbid zero newOwner to avoid triviality though not strictly required
        // but we allow zero so behaviour remains general; no tight restrictions

        // Determine who is current owner according to contract
        address currentOwner = c.owner();

        bool ok;
        // perform transferOwnership as the fuzzed caller
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: in the correct contract, transferOwnership succeeds iff caller == currentOwner.
        // We assert that relation by comparing ok to (caller == currentOwner).
        // This will hold for the reference implementation for all inputs, and the mutant (which inverts the onlyOwner check)
        // will violate it for at least some inputs (e.g., caller != currentOwner will succeed under mutant).
        assertTrue(ok == (caller == currentOwner));
    }
}

